# -*- coding: utf-8 -*-
import sys; sys.path.insert(0, "Tools/prd_ledger/76")
from _lib import c, table, save

c(1, "header lines 1-6; §2.1; §2.2 table (verbatim); §2.2 bullets", "positioning", "Way of Life - Habit Tracker (App Store ID 393159800) by Way of Life ApS (com.larsparendt.wayoflife), Health & Fitness / Productivity, released 2010-11-07, current version 4.3.2 (2026-04-20), min iOS 15.6 — a daily habit journal: items ('journals') marked green (done) / red (not done) / skip per day with optional note, read as bar/pie charts, trend lines and weekly/monthly overview; items can be good or bad (colours invert); chains/streaks from late 2015; reminders, tags, CSV/Excel export, manual backup (Dropbox early), passcode/Face ID; free tier = 3 items, premium unlimited; premium was a one-time unlock for most of its history, a subscription from 2023; listing cites press incl. Tim Ferriss's podcast with Kevin Rose; declared 25 languages but not Kazakh (#7041) or Galician (#4576); public mean above corpus mean in 21 of 22 storefronts by up to 0.38 (tw). Storefront table (verbatim): " + table("## 2.2 What the store listing says", 0), "free 3-item tier; premium one-time → subscription (2023)", "mixed", "7,764 reviews, 2010-11-08 → 2026-09-06, 83 storefronts, 27 languages (English 5,344, Chinese 538, Russian 466, Korean 263, Japanese 251, German 179, Spanish 144, Portuguese 133), corpus mean 4.62★; 5★ 5,900 (75.99%), 1–2★ 285 (3.67%)", "none", "header", "app-specific", ["7243490138", "13775690190"], "", "sixteen-year corpus spanning several product eras")

c(2, "How to read this; Seven warnings 1, 2, 4, 7; §1.1 table (verbatim); §1.2 table (verbatim); §1.3; §1.4; §1.5 table (verbatim); §1.6", "data-caveat", "Method and limits: every one of 7,764 reviews read and hand-coded in date order in batches of 100 (78 classification files), each line quoting the text behind its codes; 223 hand codes, 15 unions; 1,286 checks, 0 failures; build script refuses to write if any quotation is not verbatim; no technical duplicates (0), 26 authors on >1 storefront, 163 edited, 202 with votes (max 20). Warnings: praise corpus (any-praise 81.88%, 1–2★ 3.67%, so a Meaningful complaint is dozens not hundreds); sixteen years / several products (E6 subscription era only 906 reviews); 1,777 bodies (22.89%) ≤30 chars; NOISE 71; no version, purchase, developer-response or device fields; survivorship (E6 over-represents long-term users, TENURE_LONG ~a fifth of E6); English 5,344 vs 2,420 in 26 other languages. Signal bands (verbatim): " + table("## 1.5 Signal thresholds", 0), "n/a", "mixed", "7,764/7,764 read (100%); 223 codes; 1,286 checks; 0.1% ≈ 8 reviews, 1% ≈ 78, 5% ≈ 388", "none", "method", "generalisable", ["7243490138"], "", "")

c(3, "§0.1; §3.2 (simplicity)", "insight", "Simplicity is the product, and long-term users say so explicitly: U_PRAISE_ANY 6357 (81.88%, mean 4.80★); U_SIMPLICITY 1682 (21.66%) — PR_SIMPLE 1532 (19.73%), PR_EASY 1359 (17.50%), PR_FAST 197 (2.54%); at-a-glance picture PR_INSIGHTS 838 (10.79%); the mechanism — a grid of green/red/grey cells, three states (yes, no, skip), good or bad habits — is what users say other trackers lack: PR_BETTER_THAN 428 (5.51%), PR_YESNO 73 (0.94%), PR_SKIP 99 (1.28%). 'I've possibly tried every habit app, and keep coming back to this one' (#6339, the most-voted review, 20 votes, 2021); 'Product Managers should study this app'; 'nämlich drei Optionen anzubieten: erledigt, nicht erledigt, übersprungen'.", "free, core mechanic", "praise", "U_PRAISE_ANY 6357 / 81.88% / mean 4.80; U_SIMPLICITY 1682 / 21.66%; PR_BETTER_THAN 428 / 5.51%; PR_YESNO 73; PR_SKIP 99; High-priority", "build-free", "High-priority", "generalisable", ["7243490138", "13769488285", "13775690190", "371487225", "706035312"], "", "")

c(4, "§0.1 (keep simple); §3.5", "product-rule", "Asking the developer NOT to add features is recent and comes from veterans: PR_KEEP_SIMPLE 64 (0.82%), 61 of them in E5–E6; E6 reviewers include many long-term users — TENURE_LONG 187 of 906 E6 reviews (20.6%) vs 2.1% in E2; 'Please do not change a single thing' (#6164, de, 5★).", "kept simple over 16 years", "praise", "PR_KEEP_SIMPLE 64 / 0.82%, 61 in E5–E6; TENURE_LONG 20.6% of E6 vs 2.1% of E2", "product-rule", "Emerging", "generalisable", ["6379998517", "7243490138"], "", "the request to freeze the product grows with tenure")

c(5, "§0.2; §3.6 (frequency); §8.4", "feature", "The one structural request for fifteen years — habits that are not daily yes/no: U_FLEX_REQ 347 (4.47%, mean 4.13★, 2011-08-14 → 2026-06-03, Very strong) = REQ_FREQUENCY 214 (2.76%: specific weekdays, N times a week, weekly/monthly goals) + REQ_COUNT 129 (1.66%: quantities, several times a day) + NEG_YESNO 36 (0.46%: a partial/'yellow' state); the most frequent code in 4★ after generic praise (96 of 1,281 4★); appears in 15 of 16 calendar years 2011–2026; users work around it with skip, which distorts the percentages they value (NEG_CHART 38); a 2016 reviewer was already waiting for 'promised weekly/monthly options' (#4129); #5130 (cn, 2017) among the most-voted (6 votes). 'In my life things aren't always yes or no'; 'I try to only use skips for actual exceptions to habits, not as a scheduling method' (3★).", "absent for 15 years (daily yes/no only)", "complaint", "U_FLEX_REQ 347 / 4.47% / mean 4.13 / Very strong; REQ_FREQUENCY 214 / 2.76%; REQ_COUNT 129 / 1.66%; NEG_YESNO 36; 96 of 1,281 4★; 15 of 16 years", "must-have", "Very strong", "generalisable", ["1705374517", "2382746040", "1364445247", "1489797918", "1804926052", "453081285", "642979041"], "skip used as a scheduling workaround corrupts the stats users prize", "a promised feature (2016) still unmet ten years later")

c(6, "§0.3; §3.3; §5.2", "monetization", "The one-time unlock: praised as fair by buyers, resisted at $4.99 by non-buyers — premium was a one-time purchase ('$4.99', '30块' in China) over a free version limited to three items; MON_VALUE 342 (4.40%, mean 4.90★, 2011-06-24 → 2026-06-20, Very strong): 'it is a one time charge and it unlocks the full capabilities of the app' (4★); U_PRICE_OBJECTION 579 (7.46%, mean 3.58★, High-priority) led by MON_PRICE 306 (3.94%) and MON_FREE_LIMIT 250 (3.22%); the objection peaked when the app was young and the free tier had ads — MON_PRICE 6.7% of E2 and 6.5% of E3 vs 1.6% of E5.", "paid one-time unlock $4.99 (later $7) for unlimited items; free = 3 items", "mixed", "MON_VALUE 342 / 4.40% / mean 4.90; U_PRICE_OBJECTION 579 / 7.46% / mean 3.58; MON_PRICE 306 / 3.94%; MON_FREE_LIMIT 250 / 3.22%; MON_PRICE 6.7% E2, 6.5% E3, 1.6% E5", "build-paid", "High-priority", "generalisable", ["1397593168", "631326858", "430397979", "704025459", "773266098", "927494488"], "", "objection rate fell as the app matured and ads left the free tier")

c(7, "§0.3 (China); §6.4", "market", "China resists the $4.99 / 30-yuan price and names its buying price: China carries 82 of the 306 price objections (26.8%) and price is 15.5% of cn reviews; several name the price at which they would buy — '价格太贵了，要是12块我就买了' (the price is too high; at 12 yuan I would buy it, 5★); '30块也是最贵的' (at 30 yuan also the most expensive, 5★); one cn 5★ says the free three-habit limit is actually better ('免费版三个习惯的设定反而更好').", "one-time unlock 30 yuan", "complaint", "82 of 306 price objections (26.8%) from cn; price 15.5% of 528 cn reviews; stated buy-price 12 yuan", "research", "High-priority", "app-specific", ["631326858", "795518082", "1399309366"], "", "cn storefront, early eras")

c(8, "§0.3 (disclosure); §5.5", "dont", "The three-item limit was not always clear before download: MON_DISCLOSURE 33 (0.43%) — 'not particularly clear in the iTunes store that the free app allows for only three categories' (#415, us, 2★).", "cap not disclosed in listing", "complaint", "MON_DISCLOSURE 33 / 0.43% / Weak", "dont", "Weak", "generalisable", ["600217716"], "", "")

c(9, "§0.4; §3.3; §8.1", "timeline", "The move to a subscription broke a promise to lifetime buyers: MON_SUBSCRIPTION 40 (0.52%, mean 2.70★, 2023-05-19 → 2026-06-08, Emerging) — all 40 in E6 where they are 4.42% of 906 (Very strong within the era) and 15 of the 181 1★ in the corpus; BUG_PURCHASE 14 of 906 E6 (1.55%) vs 0.91% in E5. Three distinct complaints: lifetime buyers told they no longer have premium ('Ich hab mir die App 2015 oder so als voll Version gekauft', 1★; '之前永久内购没了？重新订阅？', 1★; 'purchased the Premium version of Way of Life as a one-time payment, not a subscription', kz 1★); new users who expected the one-time price older reviews describe ('reviews said it was a one time payment', 3★); prices differing between weeks, platforms or regions ('last week the price was $29, this week is $99', 4★). Not every veteran objects: 'grandfathered into the new system' (5★); 'no qualms about the subscription, completely worth it' (gb 5★). Support silence compounds restore failures: SUP_NONE 9 E6 — 'received no response at all' (1★).", "moved one-time premium to subscription in 2023; grandfathering inconsistent", "1★-burst", "MON_SUBSCRIPTION 40 / 0.52% / mean 2.70; 4.42% of 906 E6; 15 of 181 1★; BUG_PURCHASE 1.55% E6 vs 0.91% E5; SUP_NONE 9 E6", "product-rule", "Emerging (Very strong within E6)", "generalisable", ["13889612885", "13006973106", "10825421057", "13025777165", "13811353277", "13764730892", "13980873344", "13009268502", "9942870809"], "old reviews advertising a one-time price become a liability once the model changes", "E6 (2023–2026) only")

c(10, "§0.5; §3.4; §3.6 (sync); §8.2", "must-never-break", "Local-only data: loved for privacy, lost on updates and new phones — U_DATA_RISK 123 (1.58%, mean 3.04★, Meaningful): BUG_DATA_LOSS 38 (0.49%), NEG_BACKUP_MANUAL 13, BUG_BACKUP 10, NEG_DROPBOX_BLOCKED 18; the corresponding request is the second most frequent — REQ_SYNC 139 (1.79%, mean 4.01★, Meaningful) + REQ_AUTO_BACKUP 12; the same design is praised by others: PR_PRIVACY 12. Some losses are long histories gone after an update or a phone change because backup was manual: 'using Way of Life daily for over four years' … 'I downloaded an update and all of my data disappeared' (2★); 'for the third time, I've lost my data because I forgot to backup my data' (3★); 'I lost all my habits when I got a new phone even though I paid for the app' (5★).", "local-only storage; manual backup (Dropbox early); backup to cloud premium until 4.3.0 made it free", "complaint", "U_DATA_RISK 123 / 1.58% / mean 3.04; BUG_DATA_LOSS 38; REQ_SYNC 139 / 1.79% / mean 4.01; REQ_AUTO_BACKUP 12; PR_PRIVACY 12", "must-never-break", "Meaningful", "generalisable", ["1798965025", "13557616119", "1488838993", "493729635", "1033888911", "1106982038"], "privacy praise and data-loss complaints come from the same design", "")

c(11, "§0.5 (China Dropbox); §6.4", "market", "In China, where Dropbox is unreachable, the backup was unusable: 17 of the 18 NEG_DROPBOX_BLOCKED complaints are from cn (2014-07-18 → 2016-03-08), the other from sg — 'Dropbox中国区都屏蔽了吧' (Dropbox is blocked in China, isn't it; 3★).", "Dropbox-only backup", "blocked-conversion", "17 of 18 Dropbox complaints from cn, 2014-07 → 2016-03", "dont", "Weak", "generalisable", ["1030287079"], "", "a backup provider must be reachable in every market sold to")

c(12, "§0.6; §3.4; §7.4", "timeline", "Two update failures account for most breakage; crash waves arrive within days: U_UPDATE_REGRESSION 84 (1.08%, mean 3.08★, Meaningful); BUG_UPDATE_BROKE 54 (0.70%, mean 2.80★) — 21 of 54 from 2012-11/12 (a release that left the app unusable or corrupted data: 'latest release has left this application unusable', 1★) and 12 from 2016-05/06 (crash on 'updating journal' at launch; reviews from mx, ru, se, au, cn and us within two days: 'идет обновление журнала, и тут же приложение вылетает'); on cn 11 reviews 2015-01-23 → 2015-01-30 report crashing immediately after buying premium ('钱扣了就开始闪退，无限闪退' — the money was taken and it started crashing, endlessly; 1★). Smaller clusters: a 2014-06 redesign some called awful and greedy (NEG_UPDATE_WORSE 17: 'new version (3.0) looks awful'), a 2017-07 release that wiped some histories ('Latest update deleted my entire history', 5★), the 2023 removal of the old Today widget (NEG_LOST_FEATURE 7: 'Any updates on when the widget will be fixed?').", "several update regressions over 16 years", "1★-burst", "U_UPDATE_REGRESSION 84 / 1.08%; BUG_UPDATE_BROKE 54 / 0.70% / mean 2.80: 21 in 2012-11/12, 12 in 2016-05/06; 11 cn crash-after-purchase 2015-01-23→30; NEG_UPDATE_WORSE 17; NEG_LOST_FEATURE 7", "must-never-break", "Meaningful", "generalisable", ["694264101", "1384706437", "1001936975", "1677344652", "10369119753", "1134555630", "478785615", "693910077"], "", "")

c(13, "§0.6 (fast fixes); §3.8", "insight", "Fast fixes turn regression reviewers around: PR_SUPPORT 68 and REV_UPDATED 74 include several who returned to raise their stars — 'Has been fixed - good response' (#992, us, 5★).", "fixes crashes quickly (in some eras)", "praise", "PR_SUPPORT 68; REV_UPDATED 74", "do", "Emerging", "generalisable", ["719847792"], "", "")

c(14, "§0.7; §3.6 (platforms); §8.5", "feature", "Users want it everywhere — sync, iPad, Watch, widgets: U_PLATFORM_REQ 332 (4.28%, mean 4.14★, Very strong): REQ_SYNC 139 (1.79%), REQ_IPAD 123 (1.58%), REQ_WATCH 54 (0.70%), REQ_WIDGET 41 (0.53%), REQ_MAC 23, REQ_WEB 14, REQ_ANDROID 3; the iPad request dominates the early years (E1 4.7%); Watch and widget requests replace it from 2016 (E5 1.8% and 1.3%); several make the fifth star conditional on it (REV_STAR_TACTIC 19): 'A five star app without iCloud support is a one star app' (gb 1★); 'Five stars if I could open the app on any device and see my data' (3★); 'at this point I would pay to sync' (5★).", "absent: no sync, no iPad, no Watch; widgets only from iOS 17", "complaint", "U_PLATFORM_REQ 332 / 4.28% / mean 4.14; REQ_SYNC 139; REQ_IPAD 123; REQ_WATCH 54; REQ_WIDGET 41; REQ_MAC 23; REQ_WEB 14; REV_STAR_TACTIC 19; iPad E1 4.7% → Watch E5 1.8%, widget 1.3%", "build-paid", "Very strong", "generalisable", ["13872213199", "6948006897", "7628237879", "430397979", "651493208", "772915802"], "'I would pay to sync' — sync is a stated purchase driver", "which platform is asked for shifts with the decade")

c(15, "Warning 3; §0.8; §1.6; §7.6", "data-caveat", "Five-star bursts follow updates and rating prompts; they are not a campaign: 20 days carry 20+ reviews — 2026-04-22 (41), 2015-02-08 (34), 2025-06-05 (32), 2016-03-02 (30), 2026-02-20 (30), 2023-04-04 (29), 2012-11-19 (28), 2016-03-18 (28) and 12 more — 520 reviews (6.70%), 86.15% 5★; REV_SOLICITED 18 (0.23%, mean 4.06★, 2012-08-16 → 2018-12-09, 7 between 2015-10 and 2016-03): 'they requested that I provide a review'; the 2025–2026 bursts lean to long-term users (TENURE_LONG 65 of 200 burst reviews). No campaign marks: no generated-looking names, 2 duplicate-body groups (5 short generic reviews), 26 cross-storefront authors who are long-term users reviewing years apart; §7.6 shows the headlines hold without burst days.", "in-app rating prompts after updates", "5★-burst", "20 days ≥20 reviews = 520 (6.70%), 86.15% 5★; REV_SOLICITED 18 / 0.23%; TENURE_LONG 65 of 200 burst reviews 2025–26", "none", "Weak", "generalisable", ["1341572559", "693544347", "1143627439", "1263625007", "1341728315"], "", "")

c(16, "§0.8 (prompt backlash); §8.7", "dont", "Rating prompts annoy and are badly timed: 'Quit bugging me with review me review me crap' (#1338, us, 1★); 'app solicited a review 3 days in, after I paid for the premium version' (#3668, us, 4★) — §8.7 prompt less, and never right after a purchase.", "prompts for a rating soon after purchase", "complaint", "REV_SOLICITED 18; two quoted objections", "dont", "Weak", "generalisable", ["760754071", "1313359649"], "", "")

