c(28, "§2.2 bullets (listing gates); §2.3 table (verbatim)", "monetization", "Listing marks two features '(*) requires premium' — unlimited items and backup to cloud; release notes for 4.3.0: 'Backup & Restore is now free for all users'. Free / paid classification (verbatim): " + table("## 2.3 Free / paid / trial", 0), "free: grid, charts, notes, reminders, chains for 3 items; paid: unlimited items (one-time $4.99 / 30块 / later $7; subscription from 2023 at $30/year, £30/year, monthly); ads in early free tier gone by 2018; themes mixed; tip jar from 2018; cloud backup premium until 4.3.0; trial on subscription", "mixed", "MON_PAID 349; MON_SUBSCRIPTION 40; NEG_ADS 54 (2011-11-20 → 2020-01-15); MON_BUY_ITEMS 27; MON_TIP 15 (2018-11-29 → 2026-04-25); BUG_PURCHASE 14 in E6", "undecided", "table", "app-specific", ["5995182767", "3004389251", "5387293660", "6734062162", "10469255765", "13764730892", "13889612885"], "", "")

